/* eslint-disable @typescript-eslint/no-unused-vars */
import {
  ethers,
  Contract,
  Signer,
  BigNumber,
} from 'ethers'
import {
  TransactionRequest,
  TransactionResponse,
} from '@ethersproject/abstract-provider'

import {
  CrossChainMessenger,
  // l1BridgeName,
  // l2BridgeName,
} from '../cross-chain-messenger'
import {
  IBridgeAdapter,
  NumberLike,
  AddressLike,
  MessageDirection,
  IActionOptions,
} from '../interfaces'
import { toAddress } from '../utils'
import { Console } from '../utils/console'
import { hexStringEquals } from '../utils/hex-strings'
import { getContractInterface } from '../utils/contract-defs'
import { estimateCrossDomainMessageFee } from '../l1-provider'

/**
 * Bridge adapter for any token bridge that uses the standard token bridge interface.
 */
export class StandardBridgeAdapter implements IBridgeAdapter {
  public messenger: CrossChainMessenger
  public l1Bridge: Contract
  public l2Bridge: Contract

  /**
   * Creates a StandardBridgeAdapter instance.
   *
   * @param opts Options for the adapter.
   * @param opts.messenger Provider used to make queries related to cross-chain interactions.
   * @param opts.l1Bridge L1 bridge contract.
   * @param opts.l2Bridge L2 bridge contract.
   */
  constructor(opts: {
    messenger: CrossChainMessenger
    l1Bridge: AddressLike
    l2Bridge: AddressLike
  }) {
    this.messenger = opts.messenger

    let l1BridgeName = 'L1StandardERC20Gateway',
      l2BridgeName = 'L2StandardERC20Gateway'

    Console.log('this.messenger.contracts.l1?.[l1BridgeName]', l1BridgeName)
    this.l1Bridge = new Contract(
      toAddress(
        opts.l1Bridge
      ),
      getContractInterface(l1BridgeName),
      this.messenger.l1Provider
    )
    this.l2Bridge = new Contract(
      toAddress(
        opts.l2Bridge
      ),
      getContractInterface(l2BridgeName),
      this.messenger.l2Provider
    )
  }

  public async supportsTokenPair(
    l1Token: AddressLike,
    l2Token: AddressLike
  ): Promise<boolean> {
    try {
      // Don't support ETH deposits or withdrawals via this bridge.
      Console.log(
        'supportsTokenPair tokens',
        toAddress(l1Token),
        toAddress(l2Token)
      )
      if (
        hexStringEquals(toAddress(l1Token), ethers.constants.AddressZero) ||
        hexStringEquals(toAddress(l2Token), ethers.constants.AddressZero)
      ) {
        return false
      }

      if (
        hexStringEquals(
          toAddress(l1Token),
          this.messenger.contracts.l1.WETH?.address
        ) &&
        hexStringEquals(toAddress(l2Token), this.messenger.contracts.l2.L2WETH?.address)
      ) {
        return false
      }

      if (
        hexStringEquals(
          toAddress(l1Token),
          this.messenger.contracts.l1.USDC?.address
        ) &&
        hexStringEquals(toAddress(l2Token), this.messenger.contracts.l2.L2USDC?.address)
      ) {
        return false
      }

      if (
        hexStringEquals(
          toAddress(l1Token),
          this.messenger.contracts.l1.DAI?.address
        ) &&
        hexStringEquals(toAddress(l2Token), this.messenger.contracts.l2.L2DAI?.address)
      ) {
        return false
      }

      return true
    } catch (err) {
      // If the L2 token is not an L2StandardERC20, it may throw an error. If there's a call
      // exception then we assume that the token is not supported. Other errors are thrown. Since
      // the JSON-RPC API is not well-specified, we need to handle multiple possible error codes.
      Console.error('err 123', err)
      if (
        !err?.message?.toString().includes('CALL_EXCEPTION') &&
        !err?.stack?.toString().includes('execution reverted')
      ) {
        console.error('Unexpected error when checking bridge', err)
      }
      return false
    }
  }

  public async approval(
    l1Token: AddressLike,
    l2Token: AddressLike,
    opts: IActionOptions
  ): Promise<BigNumber> {
    // if (!(await this.supportsTokenPair(l1Token, l2Token))) {
    //   throw new Error(`token pair not supported by bridge`)
    // }

    let token = new Contract(
      toAddress(l1Token),
      getContractInterface('MorphStandardERC20'), // Any ERC20 will do
      this.messenger.l1Provider
    )

    let bridgeAddress = this.l1Bridge.address
    let signer = this.messenger.l1Signer

    Console.log('approval opts', opts, MessageDirection.L2_TO_L1)

    if (opts?.direction === MessageDirection.L2_TO_L1) {
      token = new Contract(
        toAddress(l2Token),
        getContractInterface('L2WETH'), // Any ERC20 will do
        this.messenger.l2Provider
      )

      bridgeAddress = this.l2Bridge.address
      signer = this.messenger.l2Signer
    }

    Console.log(
      'await signer.getAddress()',
      token,
      await signer.getAddress(),
      bridgeAddress
    )

    return await token.allowance(await signer.getAddress(), bridgeAddress)
  }

  public async approve(
    l1Token: AddressLike,
    l2Token: AddressLike,
    amount: NumberLike,
    signer: Signer,
    opts?: IActionOptions
  ): Promise<TransactionResponse> {
    return signer.sendTransaction(
      await this.populateTransaction.approve(l1Token, l2Token, amount, opts)
    )
  }

  public async deposit(
    l1Token: AddressLike,
    l2Token: AddressLike,
    amount: NumberLike,
    signer: Signer,
    opts?: IActionOptions
  ): Promise<TransactionResponse> {
    return signer.sendTransaction(
      await this.populateTransaction.deposit(l1Token, l2Token, amount, opts)
    )
  }

  public async withdraw(
    l1Token: AddressLike,
    l2Token: AddressLike,
    amount: NumberLike,
    signer: Signer,
    opts?: IActionOptions
  ): Promise<TransactionResponse> {
    return signer.sendTransaction(
      await this.populateTransaction.withdraw(l1Token, l2Token, amount, opts)
    )
  }

  populateTransaction = {
    approve: async (
      l1Token: AddressLike,
      l2Token: AddressLike,
      amount: NumberLike,
      opts?: IActionOptions
    ): Promise<TransactionRequest> => {
      // if (!(await this.supportsTokenPair(l1Token, l2Token))) {
      //   throw new Error(`token pair not supported by bridge`)
      // }

      let token = new Contract(
        toAddress(l1Token),
        getContractInterface('MorphStandardERC20'), // Any ERC20 will do
        this.messenger.l1Provider
      )

      let bridgeAddress = this.l1Bridge.address

      // Console.log('token approve 1', l1Token, l2Token, opts)

      if (opts?.direction === MessageDirection.L2_TO_L1) {
        token = new Contract(
          toAddress(l2Token),
          getContractInterface('L2WETH'), // Any ERC20 will do
          this.messenger.l2Provider
        )

        bridgeAddress = this.l2Bridge.address
      }
      Console.log('token approve', token.address, bridgeAddress, amount)
      return token.populateTransaction.approve(bridgeAddress, amount)
    },

    deposit: async (
      l1Token: AddressLike,
      l2Token: AddressLike,
      amount: NumberLike,
      opts?: IActionOptions
    ): Promise<TransactionRequest> => {
      // if (!(await this.supportsTokenPair(l1Token, l2Token))) {
      //   throw new Error(`token pair not supported by bridge`)
      // }
      const gasLimit = BigInt(opts?.overrides?.gasLimit?.toString() || 520000)

      // const feeData = await this.messenger.l1Provider.getFeeData();
      const gasFee = await estimateCrossDomainMessageFee(
        this.messenger.l1Provider,
        this.messenger.contracts.l1?.L1MessageQueueWithGasPriceOracle?.address,
      )
      console.log('estimateCrossDomainMessageFee gasFee.mul(gasLimit).toBigInt()', gasFee.toString(), gasLimit.toString(), gasFee.mul(gasLimit).toBigInt());
      const options = {
        value: gasFee.mul(gasLimit).toBigInt(),
      }
      Console.log(
        `depositERC20 9`,
        toAddress(l1Token),
        toAddress(opts.recipient || opts.from),
        amount,
        gasLimit,
        options
      )
      if (opts?.recipient === undefined) {
        return this.l1Bridge.populateTransaction[
          'depositERC20(address,uint256,uint256)'
        ](toAddress(l1Token), amount, gasLimit, options)
      } else {
        return this.l1Bridge.populateTransaction[
          'depositERC20(address,address,uint256,uint256)'
        ](
          toAddress(l1Token),
          toAddress(opts.recipient || opts.from),
          amount,
          gasLimit,
          options
        )
      }
    },

    withdraw: async (
      l1Token: AddressLike,
      l2Token: AddressLike,
      amount: NumberLike,
      opts?: IActionOptions
    ): Promise<TransactionRequest> => {
      // if (!(await this.supportsTokenPair(l1Token, l2Token))) {
      //   throw new Error(`token pair not supported by bridge`)
      // }
      const gasLimit = BigInt(opts?.overrides?.gasLimit?.toString() || 200_000)
      const options = {
        // ...omit(opts?.overrides || {}, 'value'),
        gasLimit,
      }

      Console.log('withdraw gasLimit', gasLimit, options)

      if (opts?.recipient === undefined) {
        return this.l2Bridge.populateTransaction[
          'withdrawERC20(address,uint256,uint256)'
        ](
          toAddress(l2Token),
          amount,
          gasLimit
          // options
        )
      } else {
        return this.l2Bridge.populateTransaction[
          'withdrawERC20(address,address,uint256,uint256)'
        ](
          toAddress(l2Token),
          toAddress(opts.recipient || opts.from),
          amount,
          gasLimit
          // options
        )
      }
    },
  }

  estimateGas = {
    approve: async (
      l1Token: AddressLike,
      l2Token: AddressLike,
      amount: NumberLike,
      opts?: IActionOptions
    ): Promise<BigNumber> => {
      return this.messenger.l1Provider.estimateGas(
        await this.populateTransaction.approve(l1Token, l2Token, amount, opts)
      )
    },

    deposit: async (
      l1Token: AddressLike,
      l2Token: AddressLike,
      amount: NumberLike,
      opts?: IActionOptions
    ): Promise<BigNumber> => {
      return this.messenger.l1Provider.estimateGas(
        await this.populateTransaction.deposit(l1Token, l2Token, amount, opts)
      )
    },

    withdraw: async (
      l1Token: AddressLike,
      l2Token: AddressLike,
      amount: NumberLike,
      opts?: IActionOptions
    ): Promise<BigNumber> => {
      return this.messenger.l2Provider.estimateGas(
        await this.populateTransaction.withdraw(l1Token, l2Token, amount, opts)
      )
    },
  }
}
